'use strict';
const $=s=>document.querySelector(s);
// Weak keys release cached render data when a page's DOM nodes are removed.
const renderKeys=new WeakMap(),htmlValues=new WeakMap(),savingVideos=new Set();
function renderChanged(selector,value){const el=$(selector);if(!el)return false;const key=JSON.stringify(value);if(renderKeys.get(el)===key)return false;renderKeys.set(el,key);return true;}
function setHTML(selector,html){const el=$(selector);if(!el||htmlValues.get(el)===html)return;el.innerHTML=html;htmlValues.set(el,html);}
const dateFormatter=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const paths={status:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',config:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',groups:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',preview:'M9 3h6 M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3 M8 15h8',records:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',cache:'M3 7l9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10',account:'M4 4h5v5H4z M15 4h5v5h-5z M4 15h5v5H4z M15 15h2v2h3v3h-5z',downloads:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',logs:'M3 4h18v16H3z M6 8l3 3-3 3 M12 15h5'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.status}"/></svg>`;
const pages={status:['运行概览','了解插件运行情况，让每一次分享都清晰可见。'],account:['B站账号','扫码登录自己的 B站账号，查看登录状态与请求冷却。'],downloads:['视频下载','下载普通视频、选择分 P，并保存到你的电脑。'],live:['直播订阅','订阅 UP 主，在指定 QQ 群接收开播和下播通知。'],config:['插件配置','调整识别与回复方式，保存后立即生效。'],groups:['群聊管理','选择在哪些群聊响应 B站分享。'],preview:['链接测试','粘贴链接，预览解析结果。测试不会向 QQ 发送消息。'],records:['解析记录','查看最近 200 条解析结果，定位分享中的问题。'],cache:['缓存管理','查看短期内容缓存与重复回复冷却。'],logs:['运行日志','查看插件最近 200 条日志，排查配置和解析问题。']};
let page='status',epoch=0,dirty=false,revision=0,config=null,manualToken='',status=null,records=[],groups=[],logRows=[],cacheRows=[],busy=false;
let latestDiagnosis=null,liveData=null,liveSnapshot=null,liveWindows=[],manualIntent=null;
const liveDirty=new Set();
paths.live='M3 5h13v14H3z M16 10l5-3v10l-5-3 M7 9l5 3-5 3z';
let toastTimer,qrTimer,qrSessionId='',qrExpires=0;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function error(message){$('#error-banner').textContent=message;$('#error-banner').hidden=false;}
function token(){if(manualToken)return manualToken;try{let value=localStorage.getItem('token')||'';if(value.startsWith('"')){try{value=JSON.parse(value);}catch{}}return typeof value==='string'?value.replace(/^Bearer\s+/i,''):'';}catch{return '';}}
async function api(path,options={}){
 const bearer=token();const res=await fetch(window.BILI_BASE+path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(bearer?{Authorization:'Bearer '+bearer}:{}),...options.headers},signal:AbortSignal.timeout(path==='/preview'?180000:20000)});
 if(res.status===401||res.status===403){$('#auth').hidden=false;throw new Error('NapCat 登录会话不可用，请重新登录管理面板。');}
 let json;try{json=await res.json();}catch{throw new Error('接口没有返回有效数据，请确认插件已更新并重载。');}
 if(!res.ok||json.code!==0)throw new Error(json.message||`请求失败（${res.status}）`);
 $('#auth').hidden=true;return json.data;
}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
function time(n){const d=new Date(n);return Number.isNaN(d.getTime())?'—':dateFormatter.format(d);}
function duration(ms){const n=Math.floor(ms/1000);return n>=3600?`${Math.floor(n/3600)} 小时 ${Math.floor(n%3600/60)} 分`:`${Math.floor(n/60)} 分 ${n%60} 秒`;}
function empty(message){return `<div class="empty"><div class="empty-symbol">◇</div>${esc(message)}</div>`;}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
const typeName=t=>({video:'视频',dynamic:'动态',opus:'图文',live:'直播间',user:'用户主页',short:'短链',article:'专栏',ep:'剧集',bangumi:'番剧',media:'影视'}[t]||t);
function validUrl(value,image=false){try{const u=new URL(value);return u.protocol==='https:'&&(image?u.hostname.endsWith('.hdslb.com'):(u.hostname==='bilibili.com'||u.hostname.endsWith('.bilibili.com')))?u.href:'';}catch{return '';}}
function resultLink(url,title){const u=validUrl(url);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(title)}</a>`:esc(title);}
function setConnection(ok){$('#connection').className='badge '+(ok?'':'error');$('#connection').textContent=ok?'● 已连接':'连接中断';}
function heading(){$('#title').textContent=pages[page][0];$('#subtitle').textContent=pages[page][1];$('#crumb').textContent=pages[page][0];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$('#page-action').innerHTML=page==='status'?'<button class="button primary" data-go="preview">＋ 测试一个链接</button>':'';}
async function navigate(next){if(!pages[next])return;if(dirty&&next!==page&&!confirm('配置尚未保存，确定离开此页吗？'))return;if(busy&&next!==page){toast('请等当前操作完成后切换页面。');return;}clearTimeout(qrTimer);qrSessionId='';page=next;dirty=false;epoch++;nextRefreshAt=0;refreshFailures=0;heading();renderKeys.delete($('#content'));$('#error-banner').hidden=true;$('#content').innerHTML=empty('正在加载…');try{await loadPage(epoch);}catch(e){error(e.message);$('#content').innerHTML=empty('暂时无法加载，请点击右上角刷新。');setConnection(false);}}
async function loadPage(stamp){
 if(page==='live'){const d=await api('/live');if(stamp!==epoch)return;renderLive(d);}
 else if(page==='status'){const d=await api('/overview');if(stamp!==epoch)return;status=d.status;records=d.records;renderStatus();}
 else if(page==='account'){const d=await api('/account');if(stamp!==epoch)return;renderAccount(d);await refreshDiagnosis();}
 else if(page==='downloads'){const d=await api('/downloads');if(stamp!==epoch)return;renderDownloads(d);}
 else if(page==='config'){const d=await api('/config');if(stamp!==epoch)return;config=d.config;revision=d.revision;renderConfig(d.cookieConfigured);}
 else if(page==='groups'){const d=await api('/groups');if(stamp!==epoch)return;groups=d.groups;renderGroups(d);}
 else if(page==='preview'){renderPreview();}
 else if(page==='records'){const d=await api('/records');if(stamp!==epoch)return;records=d.records;$('#content').innerHTML=`<div class="card"><div class="toolbar"><h2>最近解析</h2><select id="record-filter" aria-label="筛选解析结果" style="width:150px"><option value="all">全部结果</option><option value="success">成功</option><option value="error">失败</option></select></div><div id="record-table"></div></div>`;renderRecords();}
 else if(page==='cache'){const d=await api('/cache');if(stamp!==epoch)return;cacheRows=d.items;renderCache(d);}
 else if(page==='logs'){const d=await api('/logs');if(stamp!==epoch)return;logRows=d.logs;$('#content').innerHTML=`<div class="card"><div class="toolbar"><h2>运行日志</h2><select id="log-filter" aria-label="筛选日志等级" style="width:150px"><option value="all">全部等级</option><option value="info">INFO</option><option value="warn">WARN / ERROR</option><option value="debug">DEBUG</option></select></div><div id="log-list" class="logs"></div></div>`;renderLogs();}
 setConnection(true);
}
function renderStatus(){const s=status;const {uptime,...view}=s;if(!renderChanged('#content',['status',view,records.slice(0,4),riskNotice(s.risk)])){if($('#status-uptime'))$('#status-uptime').textContent=duration(uptime);return;}const cards=[['识别状态',s.enabled?'已启用':'已暂停','status','开关在插件配置中调整'],['QQ 回复成功',s.stats.success,'records',`本次运行失败 ${s.stats.failed} 次`],['页面测试',s.stats.tests+s.stats.testFailed,'preview',`其中失败 ${s.stats.testFailed} 次`],['运行时长',duration(s.uptime),'cache',`内容缓存 ${s.cacheCount} 条`]];
 $('#content').innerHTML=`${riskNotice(s.risk)}<div class="cards">${cards.map(([label,value,i,sub])=>`<div class="card"><div class="metric-label">${label}<span class="metric-icon">${icon(i)}</span></div><div class="metric"${i==='cache'?' id="status-uptime"':''}>${esc(value)}</div><div class="metric-sub">${esc(sub)}</div></div>`).join('')}</div><div class="grid"><div class="card"><div class="card-head"><h2>最近活动</h2><button class="button subtle" data-go="records">查看全部 →</button></div>${records.length?records.slice(0,4).map(r=>`<div class="kv"><div>${resultLink(r.url,r.title)}<p>${esc(time(r.time))} · ${r.source==='webui'?'页面测试':r.source==='group'?'群聊':'私聊'}</p></div>${badge(r.outcome==='success'?'成功':'失败',r.outcome==='error'?'error':'')}</div>`).join(''):empty('还没有解析记录，分享一个 B站链接试试。')}</div><div class="card"><div class="card-head"><h2>当前配置</h2>${badge('v'+s.version,'neutral')}</div>${[['群聊识别',s.groupEnabled?'开启':'关闭'],['私聊识别',s.privateEnabled?'开启':'关闭'],['群聊范围',{all:'所有群',allow:'白名单',deny:'黑名单'}[s.groupMode]],['重复回复间隔',s.cooldownSeconds+' 秒'],['B站 Cookie',s.cookieConfigured?'已配置':'未配置'],['正在处理',s.active+' 条消息 / '+s.previewActive+' 个测试']].map(([k,v])=>`<div class="kv"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></div><div class="card"><h2>快捷操作</h2><p>从一次测试开始，确认你的 B站分享能够被正确识别。</p><div class="quick">${icon('preview')}<div><strong>检查链接与回复内容</strong><p>使用当前已保存的设置，不发送 QQ 消息。</p></div><button class="button" data-go="preview">开始测试 →</button></div><div class="quick">${icon('groups')}<div><strong>管理群聊响应范围</strong><p>读取机器人已加入的群，逐个开启或关闭。</p></div><button class="button" data-go="groups">管理群聊 →</button></div></div>`;}
const boolField=(key,label,desc='')=>`<div class="switch-row"><div><label for="${key}">${label}</label>${desc?`<p>${desc}</p>`:''}</div><input class="switch" type="checkbox" id="${key}" name="${key}" ${config[key]?'checked':''}></div>`;
const numberField=(key,label,min,max,desc)=>`<div class="field"><label for="${key}">${label}</label><input type="number" id="${key}" name="${key}" min="${min}" max="${max}" required value="${config[key]}"><p>${desc}</p></div>`;
function renderConfig(cookieSet){$('#content').innerHTML=`<form id="config-form"><div class="grid"><div><div class="card"><h2>识别与回复</h2><p>决定插件何时响应，以及回复中包含哪些信息。</p>${boolField('enabled','启用 B站识别')}${boolField('groupEnabled','群聊识别')}${boolField('privateEnabled','私聊识别')}${boolField('bareIds','识别单独的 BV / AV 等编号')}${boolField('showCover','发送封面图片','图片发送失败时尝试纯文字回复。')}${boolField('showStats','显示播放、点赞等统计')}${boolField('showDescription','显示简介')}${boolField('notifyErrors','解析失败时回复简短提示')}${boolField('debug','开启调试日志')}</div><div class="card"><h2>解析参数</h2><div class="fields" style="margin-top:22px">${numberField('cooldownSeconds','重复回复间隔（秒）',0,3600,'按群聊或私聊分别计时；0 为关闭冷却。')}${numberField('maxLinks','单消息解析上限',1,5,'每条 QQ 消息最多解析 1–5 个链接。')}${numberField('timeoutSeconds','请求超时（秒）',3,30,'短链多次跳转可能需要更久。')}${numberField('descriptionLength','简介最大字数',20,1000,'超过限制的简介会截断显示。')}</div></div></div><div><div class="card"><h2>群聊范围</h2><p>也可以在群聊管理页逐个调整。</p><div class="field" style="margin-top:20px"><label for="groupMode">响应模式</label><select id="groupMode" name="groupMode">${[['all','所有群'],['allow','仅列表中的群'],['deny','排除列表中的群']].map(([v,t])=>`<option value="${v}" ${config.groupMode===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="groupIds">群号列表</label><textarea id="groupIds" name="groupIds" placeholder="多个群号用换行、空格或逗号分隔">${esc(config.groupIds)}</textarea><p>白名单模式下，列表留空表示不响应任何群。</p></div><div class="field"><label for="blockedUsers">忽略的 QQ 号</label><textarea id="blockedUsers" name="blockedUsers" placeholder="可选">${esc(config.blockedUsers)}</textarea></div></div><div class="card"><div class="card-head"><h2>B站登录状态</h2>${badge(cookieSet?'Cookie 已配置':'Cookie 未配置',cookieSet?'':'neutral')}</div><button type="button" class="button" data-go="account">打开扫码登录 →</button><p>普通公开视频通常无需填写。这里仅显示配置状态，不代表 Cookie 当前仍有效。</p><div class="field" style="margin-top:20px"><label for="cookieAction">Cookie 操作</label><select id="cookieAction"><option value="keep">保留现有 Cookie</option><option value="replace">替换为新的 Cookie</option><option value="clear">清除现有 Cookie</option></select></div><div class="field" id="cookie-field" hidden><label for="cookie">新的 Cookie</label><input type="password" id="cookie" autocomplete="new-password" placeholder="粘贴单行 Cookie"><p>仅在保存时提交，页面不会读取已有 Cookie。</p></div></div></div></div><div class="card"><h2>视频下载与请求节奏</h2><p>480P 及以上使用 DASH 音视频，需要服务器上的 FFmpeg 合并；默认目标为 480P。</p><div class="fields" style="margin-top:20px"><div class="field"><label for="downloadMode">QQ 下载方式</label><select name="downloadMode" id="downloadMode">${[['command','仅响应下载指令'],['auto','分享链接后自动下载'],['off','关闭 QQ 下载']].map(([v,t])=>`<option value="${v}" ${config.downloadMode===v?'selected':''}>${t}</option>`).join('')}</select><p>WebUI 手动下载不受此开关影响。</p></div><div class="field"><label for="playurlMode">播放地址接口</label><select name="playurlMode" id="playurlMode"><option value="wbi" ${config.playurlMode==='wbi'?'selected':''}>WBI（含 dm 参数）</option><option value="legacy" ${config.playurlMode==='legacy'?'selected':''}>旧接口（手动对照）</option></select><p>412 时不会自动切换接口重试。</p></div><div class="field"><label for="downloadQuality">清晰度上限</label><select name="downloadQuality" id="downloadQuality">${[[16,'360P'],[32,'480P'],[64,'720P'],[80,'1080P']].map(([v,t])=>`<option value="${v}" ${config.downloadQuality===v?'selected':''}>${t}</option>`).join('')}</select></div>${numberField('downloadMaxMB','单视频大小上限（MB）',10,500,'下载过程中也会检查大小。')}${numberField('downloadMaxSeconds','单视频时长上限（秒）',30,7200,'多 P 视频按当前分 P 时长判断。')}${numberField('downloadTimeoutSeconds','下载总超时（秒）',30,1800,'包括获取地址、下载和合并。')}${numberField('downloadCacheMB','缓存容量上限（MB）',100,5000,'合并阶段还需预留一份输出文件空间，必须至少为单视频上限的两倍。')}${numberField('downloadKeepHours','视频保留时间（小时）',1,72,'到期后自动清理，仅保留最近的下载记录。')}${numberField('requestGapMs','请求最小间隔（毫秒）',500,10000,'群聊、页面测试与下载元数据共用。')}${numberField('riskCooldownSeconds','412 / 429 冷却（秒）',60,3600,'触发限制后暂停请求，不连续重试。')}<div class="field"><label for="ffmpegPath">FFmpeg 可执行文件</label><input id="ffmpegPath" name="ffmpegPath" value="${esc(config.ffmpegPath)}" placeholder="ffmpeg 或服务器上的完整路径"><p>请安装在运行 NapCat 的服务器或容器里。</p></div></div></div><div class="save-bar"><span id="save-state">所有设置已同步</span><div><button type="button" id="reload-config" class="button subtle">重新加载</button> <button type="submit" id="save-config" class="button primary">保存设置</button></div></div></form>`;}
async function saveConfig(event){event.preventDefault();if(busy)return;const form=event.target;if(!form.reportValidity())return;busy=true;$('#save-config').disabled=true;const data={};for(const el of form.elements){if(!el.name)continue;data[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;}const cookieAction=$('#cookieAction').value;if(cookieAction==='replace')data.cookie=$('#cookie').value;
 try{const d=await post('/config',{config:data,revision,cookieAction});config=d.config;revision=d.revision;dirty=false;renderConfig(d.cookieConfigured);$('#error-banner').hidden=true;toast('设置已保存并立即生效');}catch(e){error(e.message);}finally{busy=false;if($('#save-config'))$('#save-config').disabled=false;}}
function renderGroups(d){$('#content').innerHTML=`${!d.groupEnabled?'<div class="notice">群聊识别总开关已关闭。下面设置会保留；请在插件配置中开启总开关后生效。</div>':''}<div class="card"><div class="toolbar"><div><h2>机器人加入的群</h2><p>共 ${groups.length} 个群 · 调整开关后自动保存</p></div><input id="group-search" type="search" placeholder="搜索群名或群号" aria-label="搜索群"></div><div id="group-table"></div></div>`;renderGroupTable();}
function renderGroupTable(){const q=($('#group-search')?.value||'').trim().toLowerCase();const rows=groups.filter(g=>(g.name+' '+g.id).toLowerCase().includes(q));$('#group-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>群聊</th><th>成员数</th><th>允许识别</th></tr></thead><tbody>${rows.map(g=>`<tr><td class="title-cell"><strong>${esc(g.name)}</strong><small>${esc(g.id)}</small></td><td>${g.members}</td><td><input class="switch group-toggle" type="checkbox" aria-label="${esc(g.name)}允许识别" data-id="${esc(g.id)}" ${g.enabled?'checked':''}></td></tr>`).join('')}</tbody></table></div>`:empty('没有找到匹配的群聊。');}
function renderPreview(){$('#content').innerHTML=`<div class="card"><div class="card-head"><div><h2>测试一个 B站分享</h2><p>支持完整链接、b23 短链、BV / AV 等编号。</p></div>${badge('只在页面预览','neutral')}</div><form id="preview-form"><label for="preview-input">链接或编号</label><textarea id="preview-input" maxlength="2000" required placeholder="例如：https://www.bilibili.com/video/BV…"></textarea><div class="toolbar" style="margin-top:17px;margin-bottom:0"><p>使用已保存配置，可同时测试多个链接。</p><button id="run-preview" class="button primary" type="submit">开始解析 →</button></div></form></div><div id="preview-result">${empty('解析结果会显示在这里。')}</div>`;}
async function preview(event){event.preventDefault();if(busy)return;busy=true;const stamp=epoch;$('#run-preview').disabled=true;$('#run-preview').textContent='正在解析…';$('#preview-result').innerHTML=empty('正在获取 B站内容，请稍候…');try{const d=await post('/preview',{input:$('#preview-input').value});if(stamp!==epoch)return;$('#error-banner').hidden=true;$('#preview-result').innerHTML=d.results.map(r=>r.ok?`<div class="card"><div class="card-head"><h2>回复预览 · ${esc(r.type)}</h2>${badge(r.limited?'仅链接识别':'解析成功',r.limited?'neutral':'')}</div><div class="preview-card">${(r.images||[]).filter(x=>validUrl(x,true)).map(x=>`<img src="${esc(x)}" alt="内容封面" referrerpolicy="no-referrer">`).join('')}<pre class="preview-text">${esc(r.text)}</pre></div><p style="margin-top:18px">${resultLink(r.url,'在 B站打开 ↗')}</p></div>`:`<div class="notice error">${esc(r.type)}：${esc(r.message)}</div>`).join('');}catch(e){if(stamp===epoch)$('#preview-result').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}finally{busy=false;if($('#run-preview')){$('#run-preview').disabled=false;$('#run-preview').textContent='开始解析 →';}}}
function renderRecords(){const filter=$('#record-filter').value;if(!renderChanged('#record-table',[filter,records]))return;const rows=records.filter(r=>filter==='all'||r.outcome===filter);$('#record-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>内容 / 结果</th><th>来源</th><th>状态</th><th>耗时</th><th>时间</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title-cell">${resultLink(r.url,r.title)}<small>${esc(typeName(r.type))}</small></td><td>${r.source==='webui'?'页面测试':r.source==='group'?'群聊':'私聊'}<small>${esc(r.scope?.split(':')[1]||'')}</small></td><td>${badge(r.outcome==='success'?'成功':'失败',r.outcome==='error'?'error':'')}</td><td>${r.duration} ms</td><td>${esc(time(r.time))}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无符合条件的解析记录。');}
function renderLogs(){const filter=$('#log-filter').value;if(!renderChanged('#log-list',[filter,logRows]))return;const rows=logRows.filter(r=>filter==='all'||r.level===filter||(filter==='warn'&&r.level==='error'));$('#log-list').innerHTML=rows.length?rows.map(r=>`<div class="log"><time>${esc(time(r.time))}</time><span class="${esc(r.level)}">${esc(r.level.toUpperCase())}</span><span>${esc(r.message)}</span></div>`).join(''):empty('暂无此等级的日志。');}
function renderCache(d){$('#content').innerHTML=`<div class="notice">内容缓存约 60 秒，减少重复请求；冷却用于避免在同一会话反复回复。清理会同时重置两者。</div><div class="card"><div class="toolbar"><div><h2>内容缓存</h2><p>${d.items.length} 条有效缓存 · ${d.cooldownCount} 条冷却记录</p></div><button id="clear-cache" class="button danger">清除缓存与冷却</button></div>${d.items.length?`<div class="table-wrap"><table><thead><tr><th>内容</th><th>类型</th><th>失效时间</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${resultLink(x.url,x.title)}</td><td>${esc(x.type)}</td><td>${esc(time(x.expiresAt))}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无有效内容缓存。')}</div>`;}
$('#nav').innerHTML=Object.entries(pages).map(([id,[title]])=>`<button data-page="${id}">${icon(id)}${title}</button>`).join('');
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const go=b.dataset.page||b.dataset.go;if(go){navigate(go);return;}
 if(b.id==='refresh'||b.id==='reload-config'){if(busy){toast('请等待当前操作完成。');return;}if(dirty&&!confirm('重新加载会丢弃未保存设置，确定继续吗？'))return;dirty=false;await navigate(page);}
 if(b.id==='auth-connect'){manualToken=$('#auth-token').value.trim().replace(/^Bearer\s+/i,'');$('#auth-token').value='';await navigate(page);}
 if(b.id==='theme'){const dark=document.body.classList.toggle('dark');try{localStorage.setItem('bili-webui-theme',dark?'dark':'light');}catch{}b.textContent=dark?'切换浅色外观':'切换深色外观';}
 if(b.id==='clear-cache'){b.disabled=true;try{await post('/cache/clear');toast('缓存和冷却已清理');await loadPage(epoch);}catch(e){error(e.message);}finally{b.disabled=false;}}
});
document.addEventListener('input',e=>{if(e.target.closest('#live-settings-form,#live-subscription-form')){dirty=true;liveDirty.add(e.target.closest('form').id);}if(e.target.closest('#config-form')){dirty=true;$('#save-state').textContent='有未保存的修改';}if(e.target.id==='group-search')renderGroupTable();});
document.addEventListener('change',async e=>{if(e.target.id==='cookieAction'){$('#cookie-field').hidden=e.target.value!=='replace';$('#cookie').required=e.target.value==='replace';}if(e.target.id==='record-filter')renderRecords();if(e.target.id==='log-filter')renderLogs();if(e.target.classList.contains('group-toggle')){const el=e.target;const old=!el.checked;el.disabled=true;try{await post('/groups/toggle',{id:el.dataset.id,enabled:el.checked});const g=groups.find(x=>x.id===el.dataset.id);if(g)g.enabled=el.checked;toast('群聊设置已保存');}catch(err){el.checked=old;error(err.message);}finally{el.disabled=false;}}});
document.addEventListener('submit',e=>{if(e.target.id==='config-form')saveConfig(e);if(e.target.id==='preview-form')preview(e);if(e.target.id==='download-form')startDownload(e);if(e.target.id==='diagnosis-form')runDiagnosis(e);});
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
try{const saved=localStorage.getItem('bili-webui-theme');if(saved==='dark'||(!saved&&matchMedia('(prefers-color-scheme: dark)').matches)){document.body.classList.add('dark');$('#theme').textContent='切换浅色外观';}}catch{}
let polling=false,nextRefreshAt=0,refreshFailures=0;
async function refreshPage(){
 if(document.hidden||polling||busy||Date.now()<nextRefreshAt||!['status','records','logs','downloads','account','live'].includes(page))return;
 polling=true;const stamp=epoch;let active=false;
 try{
  if(page==='live'){const d=await api('/live');if(stamp===epoch)renderLiveRows(d);active=d.running||d.manualSending?.length>0;}
  else if(page==='account'){await refreshDiagnosis();active=latestDiagnosis?.report?.status==='running';}
  else if(page==='status'){const d=await api('/overview');if(stamp===epoch){status=d.status;records=d.records;renderStatus();}active=d.status.active>0||d.status.previewActive>0;}
  else if(page==='records'){const d=await api('/records');if(stamp===epoch){records=d.records;renderRecords();}}
  else if(page==='downloads'){const d=await api('/downloads');if(stamp===epoch)renderJobs(d);active=d.jobs.some(j=>['queued','downloading','sending'].includes(j.status));}
  else{const d=await api('/logs');if(stamp===epoch){logRows=d.logs;renderLogs();}}
  if(stamp===epoch){setConnection(true);refreshFailures=0;nextRefreshAt=Date.now()+(active?5000:15000);}
 }catch{if(stamp===epoch){setConnection(false);refreshFailures=Math.min(refreshFailures+1,3);nextRefreshAt=Date.now()+Math.min(60000,15000*2**(refreshFailures-1));}}
 finally{polling=false;}
}
setInterval(refreshPage,5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){nextRefreshAt=0;void refreshPage();}});
navigate('status');

function riskNotice(risk){return risk?.pausedUntil>Date.now()?`<div class="notice error">B站请求处于冷却中，约 ${Math.ceil((risk.pausedUntil-Date.now())/1000)} 秒后可再试。扫码登录不会自动解除服务器 IP 或请求频率限制。</div>`:'';}
function renderAccount(d){
 const names={none:'未登录',unchecked:'已保存凭据，尚未验证',saved:'扫码成功，凭据已保存',valid:'登录有效',expired:'登录已失效',unknown:'暂时无法验证'};
 $('#content').innerHTML=`${riskNotice(d.risk)}<div class="grid"><div class="card"><div class="card-head"><div><h2>当前 B站账号</h2><p>登录信息保存在服务器，不会在页面回显 Cookie。</p></div>${badge(names[d.state]||'未知状态',d.state==='valid'?'':'neutral')}</div><div class="kv"><span>账号</span><strong>${esc(d.name||'尚未获取昵称')}</strong></div><div class="kv"><span>UID</span><strong>${esc(d.uid||'—')}</strong></div><div class="kv"><span>最近验证</span><strong>${d.checkedAt?esc(time(d.checkedAt)):'尚未验证'}</strong></div><div class="inline" style="margin-top:20px"><button id="account-check" class="button">检查登录状态</button><button id="account-remove" class="button danger" ${d.configured?'':'disabled'}>移除本插件登录</button></div><p style="margin-top:14px">移除只清除本插件保存的凭据，不会注销手机上的 B站账号，也不等于撤销 B站服务端会话。</p></div><div class="card"><h2>使用 B站 App 扫码</h2><p>生成二维码后，用手机 B站 App 扫描，并在手机上确认登录。</p><div id="qr-view" class="empty">二维码会显示在这里</div><p id="qr-state" role="status"></p><div class="inline"><button id="qr-generate" class="button primary">生成登录二维码</button><button id="qr-cancel" class="button subtle">取消</button></div></div></div><div class="notice">412 不一定是账号问题。插件默认将业务请求间隔设为 1.5 秒；遇到 412 / 429 时暂停至少 5 分钟。若登录后仍持续受限，请等冷却结束并检查服务器网络。</div>${diagnosisCard()}`;
 renderDiagnosis();
}
async function pollLogin(){
 const sessionId=qrSessionId;if(!sessionId||page!=='account')return;
 if(Date.now()>qrExpires){$('#qr-state').textContent='二维码已过期，请重新生成。';$('#qr-view').innerHTML=empty('二维码已过期');qrSessionId='';return;}
 try{const d=await post('/account/poll',{sessionId});if(qrSessionId!==sessionId||page!=='account')return;
  if(d.state==='success'){qrSessionId='';renderAccount({configured:true,state:'saved',uid:d.uid});$('#qr-view').innerHTML=empty('✓ 扫码成功，登录凭据已保存');$('#qr-state').textContent='点击“检查登录状态”可查看账号昵称。';toast('B站扫码登录成功');return;}
  if(d.state==='expired'){qrSessionId='';$('#qr-view').innerHTML=empty('二维码已过期');$('#qr-state').textContent='请重新生成二维码。';return;}
  $('#qr-state').textContent=d.state==='scanned'?'已扫码，请在手机上确认登录。':'等待手机扫码…';qrTimer=setTimeout(pollLogin,5000);
 }catch(e){if(qrSessionId===sessionId&&page==='account'){$('#qr-state').textContent=e.message+' 请重新生成二维码。';qrSessionId='';}}
}
function renderDownloads(d){$('#content').innerHTML=`<div id="download-risk">${riskNotice(d.risk)}</div><div class="card"><div class="card-head"><div><h2>下载到服务器，再保存到电脑</h2><p>默认上限 ${d.config.maxMB} MB / ${d.config.maxSeconds} 秒；保留 ${d.config.keepHours} 小时。最多 3 个任务，顺序执行。清晰度上限：${window.BiliDownloadDetails.quality(d.config.quality)}；480P 及以上需要 FFmpeg。</p></div><button id="engine-check" class="button">检查 FFmpeg</button></div><p id="engine-result"></p><form id="download-form" style="margin-top:16px"><div class="fields"><div class="field"><label for="download-input">视频链接或 BV / AV 号</label><input id="download-input" required maxlength="2000" placeholder="https://www.bilibili.com/video/BV…"></div><div class="field"><label for="download-page">分 P</label><input id="download-page" type="number" min="1" max="1000" value="1" required></div></div><div class="toolbar" style="margin-bottom:0"><p>QQ 用法：/bili下载 视频链接 P2</p><button id="download-start" class="button primary">加入下载队列</button></div></form></div><div class="card"><div class="toolbar"><h2>下载任务</h2><button id="downloads-clear" class="button danger">清理已下载文件</button></div><div id="download-jobs"></div></div>`;renderJobs(d);}
function renderJobs(d){if(!$('#download-jobs'))return;setHTML('#download-risk',riskNotice(d.risk));if(!renderChanged('#download-jobs',[d.jobs,[...savingVideos]]))return;const openJobs=new Set([...document.querySelectorAll('details.download-failure[open]')].map(e=>e.dataset.job));const statuses={queued:'排队中',downloading:'下载中',sending:'发送 QQ 中',done:'已完成',cancelled:'已取消',error:'失败',expired:'文件已清理'};
 $('#download-jobs').innerHTML=d.jobs.length?`<div class="table-wrap"><table><thead><tr><th>视频</th><th>状态 / 进度</th><th>大小 / 清晰度</th><th>操作</th></tr></thead><tbody>${d.jobs.map(j=>`<tr><td class="title-cell"><strong>${esc(j.title)}</strong><small>P${j.page} · ${esc(time(j.createdAt))}</small>${j.error?`<p class="danger">${esc(j.error)}</p>`:''}${j.sendError?`<p class="danger">${esc(j.sendError)}</p>`:''}${j.qualityNotice?`<p>${esc(j.qualityNotice)}</p>`:''}${window.BiliDownloadDetails.render(j,openJobs.has(j.id))}</td><td>${badge(statuses[j.status]||j.status,j.status==='error'?'error':'neutral')}<small>${esc(j.stage||'')}${j.status==='downloading'?` · ${((j.downloaded||0)/1048576).toFixed(1)} MB`:''}</small></td><td>${((j.bytes||j.downloaded||0)/1048576).toFixed(1)} MB<small>实际：${window.BiliDownloadDetails.quality(j.quality)}${j.requestedQuality?` / 目标：${window.BiliDownloadDetails.quality(j.requestedQuality)}`:''}</small></td><td>${j.status==='done'&&j.fileReady?`<button class="button primary file-save" data-id="${esc(j.id)}" ${savingVideos.has(j.id)?'disabled':''}>${savingVideos.has(j.id)?'正在传输…':'保存到电脑'}</button>`:''}${['queued','downloading'].includes(j.status)?`<button class="button download-cancel" data-id="${esc(j.id)}">取消任务</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有下载任务。');}
async function startDownload(event){event.preventDefault();if(busy)return;busy=true;$('#download-start').disabled=true;try{await post('/downloads/start',{input:$('#download-input').value,page:Number($('#download-page').value)});nextRefreshAt=0;toast('已加入下载队列');renderJobs(await api('/downloads'));}catch(e){error(e.message);}finally{busy=false;if($('#download-start'))$('#download-start').disabled=false;}}
async function saveVideo(id,button){
 if(savingVideos.has(id))return;savingVideos.add(id);button.disabled=true;button.textContent='正在传输…';try{
  const bearer=token(),res=await fetch(window.BILI_BASE+'/downloads/file/'+encodeURIComponent(id),{credentials:'same-origin',headers:bearer?{Authorization:'Bearer '+bearer}:{},signal:AbortSignal.timeout(900000)});
  if(!res.ok){let message='文件传输失败，请刷新任务列表。';try{message=(await res.json()).message||message;}catch{}throw new Error(message);}
  const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bilibili-'+id.slice(0,8)+'.mp4';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('已交给浏览器保存');
 }catch(e){error(e.message);}finally{savingVideos.delete(id);button.disabled=false;button.textContent='保存到电脑';for(const el of document.querySelectorAll('.file-save'))if(el.dataset.id===id){el.disabled=false;el.textContent='保存到电脑';}}
}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.classList.contains('download-diagnostic-export')){b.disabled=true;try{const data=await api('/downloads/diagnostic/'+encodeURIComponent(b.dataset.id));const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bili-download-'+b.dataset.id+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出此任务诊断');}catch(e){error(e.message);}finally{b.disabled=false;}return;}
 if(b.classList.contains('file-save')){await saveVideo(b.dataset.id,b);return;}
 const ids=['account-check','account-remove','qr-generate','qr-cancel','engine-check','downloads-clear'];if(!ids.includes(b.id)&&!b.classList.contains('download-cancel'))return;
 if(busy){toast('请等待当前操作完成。');return;}busy=true;b.disabled=true;try{
  if(b.id==='account-check'){clearTimeout(qrTimer);qrSessionId='';renderAccount(await post('/account/check'));}
  if(b.id==='account-remove'){clearTimeout(qrTimer);qrSessionId='';await post('/account/remove');renderAccount(await api('/account'));toast('已移除本插件保存的登录');}
  if(b.id==='qr-generate'){clearTimeout(qrTimer);qrSessionId='';$('#error-banner').hidden=true;$('#qr-view').innerHTML=empty('正在生成二维码…');$('#qr-state').textContent='';const d=await post('/account/qr');if(page!=='account')return;qrSessionId=d.sessionId;qrExpires=d.expiresAt;$('#qr-view').innerHTML=d.image.startsWith('data:image/svg+xml;base64,')?`<img class="login-qr" src="${esc(d.image)}" alt="请使用 B站 App 扫描登录二维码">`:'';$('#qr-state').textContent='请在 3 分钟内扫码并确认。';qrTimer=setTimeout(pollLogin,5000);}
  if(b.id==='qr-cancel'){clearTimeout(qrTimer);qrSessionId='';await post('/account/cancel');$('#qr-view').innerHTML=empty('登录已取消');$('#qr-state').textContent='';}
  if(b.id==='engine-check'){const d=await post('/downloads/engine');$('#engine-result').textContent=d.available?'✓ FFmpeg 可用，可以合并音视频。':'未检测到 FFmpeg。请在服务器安装，或在插件配置中填写可执行文件路径。';}
  if(b.id==='downloads-clear'){await post('/downloads/clear');renderJobs(await api('/downloads'));toast('下载文件已清理');}
  if(b.classList.contains('download-cancel')){await post('/downloads/cancel',{id:b.dataset.id});renderJobs(await api('/downloads'));}
 }catch(e){error(e.message);if(b.id==='qr-generate'&&page==='account'){$('#qr-view').innerHTML=empty('二维码未生成');$('#qr-state').textContent=e.message;}}finally{busy=false;b.disabled=false;}
});

function diagnosisCard(){return `<div class="card"><h2>B站 412 自检</h2><p>下载中断或写入失败的详情，请在 <button type="button" class="button subtle" data-go="downloads">视频下载 → 错误详情</button> 查看。</p><p>顺序检查主页、NAV、VIEW、PLAYER V2 与播放地址。触发风控后停止后续请求；不会下载视频文件或发送 QQ。</p><form id="diagnosis-form"><div class="fields"><div class="field"><label for="diagnosis-input">测试视频 BV / AV 或链接</label><input id="diagnosis-input" required maxlength="2000" placeholder="请输入你遇到问题的普通视频链接"></div><div class="field"><label for="diagnosis-mode">请求身份</label><select id="diagnosis-mode"><option value="session">当前保存的会话</option><option value="anonymous">未登录</option><option value="both">先未登录，再当前会话</option></select></div></div><div class="inline"><button id="diagnosis-start" class="button primary">运行 B站连接自检</button><button id="diagnosis-export" type="button" class="button">导出脱敏结果</button></div></form><div id="diagnosis-result" style="margin-top:20px"></div></div>`;}
function renderDiagnosis(){const target=$('#diagnosis-result');if(!target||!renderChanged('#diagnosis-result',latestDiagnosis?.report||null))return;const d=latestDiagnosis?.report;if(!d){target.innerHTML=empty('尚未运行自检。运行后可导出结果用于排查。');return;}
 target.innerHTML=`<p>${esc(d.conclusion)}</p><p>测试视频：${esc(d.video)} · ${esc(time(d.startedAt))} · ${d.status==='running'?'执行中':'已结束'}</p><div class="table-wrap"><table><thead><tr><th>身份 / 接口</th><th>HTTP_STATUS</th><th>BILI_CODE</th><th>状态</th><th>说明</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.mode==='anonymous'?'未登录':'保存会话'}<small>${esc(r.endpoint)}</small></td><td>${r.httpStatus??'—'}</td><td>${r.biliCode??'—'}</td><td>${esc({ok:'正常',anonymous:'未登录',risk:'风控',error:'错误',skipped:'未请求',blocked:'冷却未请求',pending:'处理中'}[r.status]||r.status)}</td><td>${esc(r.reason||'')}${r.actualEndpoint&&r.actualEndpoint!==r.endpoint?`<small>实际响应：${esc(r.actualEndpoint)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`;
 if($('#diagnosis-start'))$('#diagnosis-start').disabled=d.status==='running';
}
async function refreshDiagnosis(){const stamp=epoch;const d=await api('/diagnostics/summary');if(page!=='account'||stamp!==epoch)return;latestDiagnosis=d;renderDiagnosis();}
async function runDiagnosis(e){e.preventDefault();if(busy)return;busy=true;$('#diagnosis-start').disabled=true;try{await post('/diagnostics/start',{input:$('#diagnosis-input').value,mode:$('#diagnosis-mode').value});nextRefreshAt=0;await refreshDiagnosis();toast('自检已开始，结果会自动更新');}catch(e){error(e.message);}finally{busy=false;if($('#diagnosis-start'))$('#diagnosis-start').disabled=latestDiagnosis?.report?.status==='running';}}
document.addEventListener('click',async e=>{if(e.target.closest('button')?.id!=='diagnosis-export')return;try{const full=await api('/diagnostics');if(!full?.report){toast('请先运行一次自检');return;}const blob=new Blob([JSON.stringify(full,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bili-412-diagnostic.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e.message);}});

function renderLiveWindows(){
 $('#live-window-list').innerHTML=liveWindows.map((w,i)=>`<div class="live-window-row"><div class="field"><label for="live-window-start-${i}">时段 ${i+1} · 开始</label><input id="live-window-start-${i}" type="time" required value="${esc(w.startTime)}"></div><div class="field"><label for="live-window-end-${i}">结束（北京时间）</label><input id="live-window-end-${i}" type="time" required value="${esc(w.endTime)}"></div><button type="button" class="button danger" id="live-window-remove-${i}" aria-label="删除时段 ${i+1}">删除</button></div>`).join('');
 $('#live-window-add').disabled=liveWindows.length>=12;
}
function readLiveWindows(){return liveWindows.map((_,i)=>({startTime:$('#live-window-start-'+i).value,endTime:$('#live-window-end-'+i).value}));}
function liveFeedback(message,focus=true){const el=$('#live-action-status');if(!el)return;el.textContent=message;el.hidden=false;if(focus){el.scrollIntoView?.({behavior:'smooth',block:'center'});el.focus?.({preventScroll:true});}}
function prepareManualNotification(b){
 const d=liveSnapshot||liveData,sub=d.subscriptions.find(s=>s.uid===b.dataset.uid),record=b.dataset.record&&d.records.find(r=>r.id===b.dataset.record);
 if(!sub||(b.dataset.record&&!record)){liveFeedback('订阅或记录已变化，请刷新后重试。');return;}
 manualIntent={revision:d.revision,uid:sub.uid,kind:b.dataset.kind,...(record?{recordId:record.id}:{})};
 const groups=record?[record.group]:sub.groups;
 $('#live-manual-panel').innerHTML=`<strong>确认发送${b.dataset.kind==='start'?'开播':'下播'}通知</strong><p>主播：${esc(sub.label||'UID '+sub.uid)}<br>目标群：${groups.map(esc).join('、')}</p><p>请先检查群里是否已收到，避免重复发送。${record?'本次仅补发这条记录对应的群。':''}此操作不访问 B站。</p><div class="inline"><button type="button" class="button primary" id="live-manual-send">确认发送</button><button type="button" class="button" id="live-manual-cancel">取消</button></div>`;
 $('#live-manual-panel').hidden=false;liveFeedback('请核对下方主播和目标群，再点击「确认发送」。');$('#live-manual-send').focus?.({preventScroll:true});
}
function renderLive(d){
 liveData=d;liveDirty.clear();manualIntent=null;
 liveWindows=(d.windows??[{startTime:d.startTime||'18:00',endTime:d.endTime||'23:00'}]).map(w=>({...w}));
 $('#content').innerHTML=`${riskNotice(d.risk)}${d.loadError?`<div class="notice error">${esc(d.loadError)}</div>`:''}<div class="notice">新增或重新启用时先记录当前状态，不补发已在进行的直播。可按北京时间限定检测时段；默认发现开播后持续检测到下播，连续两次检测到未直播才发下播通知。此功能独立于链接识别开关，通知发往下方指定的群。</div><div class="grid"><div class="card"><h2>直播通知设置</h2><form id="live-settings-form"><div class="switch-row"><label for="live-enabled">启用直播检测</label><input class="switch" type="checkbox" id="live-enabled" ${d.enabled?'checked':''}></div><div class="field"><label for="live-interval">检查间隔（秒）</label><input id="live-interval" type="number" min="30" max="3600" required value="${d.intervalSeconds}"><p>30–3600 秒。订阅较多、接口冷却或发送较慢时，实际检查间隔会延长。</p></div><div class="switch-row"><label for="live-window-enabled">仅在指定时段检测</label><input class="switch" type="checkbox" id="live-window-enabled" ${d.scheduleEnabled?'checked':''}></div><div id="live-window-list"></div><button type="button" id="live-window-add" class="button">＋ 添加时间段</button><p>最多 12 段，北京时间；任意一段命中就检测，重叠不会重复查询。支持跨午夜，如 22:00–02:00；开始包含、结束不包含。关闭时段限制则全天检测。</p><div class="switch-row"><label for="live-follow">发现开播后持续检测到下播</label><input class="switch" type="checkbox" id="live-follow" ${d.continueUntilEnd!==false?'checked':''}></div><p>开启后，时段外只跟踪已在直播的主播。手动停止始终优先。</p><button class="button primary" type="submit">保存通知设置</button></form><div class="inline" style="margin-top:18px"><button id="live-detect-start" type="button" class="button primary">手动开始检测</button><button id="live-detect-stop" type="button" class="button danger">手动停止检测</button><button id="live-detect-auto" type="button" class="button">恢复自动时段</button></div><p>手动开始可在时段外检测，逐个主播确认下播后恢复自动时段。手动停止会一直保持，重启也不会自行恢复。请先保存表单再操作。</p><p id="live-schedule" style="margin-top:16px">${d.running?'正在检查直播状态':d.nextCheckAt?`下次检查约 ${esc(time(d.nextCheckAt))}`:'通知未运行'}。<button class="button subtle" id="live-refresh" type="button">刷新状态与记录</button></p></div><div class="card"><h2>通知卡片</h2><p>开播／下播通知默认渲染成图片卡片：直播封面、头像、直播间二维码，配上爱弥斯（《鸣潮》角色，星炬学院学生、隧者适格者，官方性格描述为活泼俏皮）的口吻。卡片由外部文转图服务渲染，未配置地址时自动改用「封面 + 文案」。</p><div id="live-card-panel"></div></div><div class="card"><h2 id="live-form-title">添加／修改订阅</h2><p>支持 UP 主 UID 和直播间号，个人空间或直播间链接也可直接粘贴。相同 UID 会更新原订阅，最多 20 位主播。</p><form id="live-subscription-form"><div class="fields"><div class="field"><label for="live-input-type">纯数字输入的类型</label><select id="live-input-type"><option value="uid">UP 主 UID</option><option value="room">直播间号</option></select></div><div class="field"><label for="live-input">UID、直播间号或链接</label><input id="live-input" required maxlength="500" placeholder="https://live.bilibili.com/…"></div></div><div class="field"><label for="live-label">主播备注（可选）</label><input id="live-label" maxlength="80" placeholder="默认使用 B站主播昵称"></div><div class="field"><label for="live-groups">通知 QQ 群号</label><textarea id="live-groups" required rows="2" placeholder="多个群用换行或逗号分隔"></textarea><p>请填写机器人已加入且能发言的群。群聊识别的白名单／黑名单不影响这里的通知目标。</p><button class="button subtle" id="live-load-groups" type="button">从机器人群列表选择</button><div id="live-group-options"></div></div><div class="switch-row"><label for="live-sub-enabled">启用此订阅</label><input class="switch" type="checkbox" id="live-sub-enabled" checked></div><div class="switch-row"><label for="live-start">开播通知</label><input class="switch" type="checkbox" id="live-start" checked></div><div class="switch-row"><label for="live-end">下播通知（包含估算时长）</label><input class="switch" type="checkbox" id="live-end" checked></div><div class="inline"><button class="button primary" type="submit">验证主播并保存订阅</button><button class="button subtle" id="live-reset-form" type="button">清空表单</button></div></form></div></div><div class="card"><h2>已订阅主播 · ${d.subscriptions.length} / 20</h2><p>“手动发开播／下播”直接向此主播配置的群发送消息，不请求 B站、不修改实际检测状态，也不解除手动停止。检测失败时，可先手动开始检测并按需补发。</p><div id="live-action-status" class="notice" role="status" tabindex="-1" hidden></div><div id="live-manual-panel" class="notice" hidden></div><div id="live-subscriptions"></div></div><div class="card"><h2>最近通知</h2><p>发送失败或回执超时不会自动重发，避免群里收到重复通知。“提交中／结果未知”也可能是插件重载时未取得回执，请查看实际群消息。</p><div id="live-records"></div></div>`;
 renderLiveWindows();renderLiveRows(d);
 void renderLiveCardPanel();
}
// —— 通知卡片面板 ——
let liveCardStatus=null;
function cardSelect(id,label,value,options,description){
 return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>${description?`<p>${esc(description)}</p>`:''}</div>`;
}
async function renderLiveCardPanel(){
 const box=$('#live-card-panel');if(!box)return;
 let d;try{d=await api('/live/card');}catch(e){box.innerHTML=`<div class="notice error">读取卡片设置失败：${esc(e.message)}</div>`;return;}
 liveCardStatus=d;
 const status=d.status?.at?`最近一次渲染：${d.status.ok?'成功':'失败'}（${esc(time(d.status.at))}${d.status.ms?` · ${d.status.ms} ms`:''}）${d.status.ok?'':` · ${esc(d.status.reason)}`}`:'本次运行还没有渲染过卡片';
 box.innerHTML=`${d.configured?'':`<div class="notice error">${esc(d.hint||'尚未填写文转图服务地址，通知会使用「封面 + 文案」。')}</div>`}<div class="switch-row"><label for="live-card-toggle">使用图片卡片</label><input class="switch" type="checkbox" id="live-card-toggle" ${d.enabled?'checked':''}></div><div class="fields">${cardSelect('live-card-persona','通知口吻',d.persona,(d.personas||[]).map(p=>[p.key,p.label]),'爱弥斯为默认口吻，另有软萌与朴素两种。')}${cardSelect('live-card-theme','卡片配色',d.theme,(d.themes||[]).map(t=>[t,{amis:'爱弥斯蓝粉',pink:'B站粉',min:'极简'}[t]||t]))}${cardSelect('live-card-decor','卡片装饰',d.decor,[['auto','自动：有自备贴纸就用'],['builtin','仅内置装饰'],['off','不叠加贴纸']],'贴纸放在插件 assets/card/custom/ 目录，前缀 top- / tag- / corner- 决定位置。')}${cardSelect('live-card-avatar-pos','头像取景位置',d.avatarPosition,[['center 35%','偏上（默认，适合头顶贴边）'],['center center','居中'],['center 65%','偏下（适合人物偏下）'],['center 20%','取上部三分之一'],['center 80%','取下部三分之一']],'头像是圆形显示，方图的四角会被切掉；人物头顶被切或偏下时换一个取景位置。')}</div><div class="field"><label for="live-card-url">文转图服务地址</label><input id="live-card-url" value="${esc(d.renderUrl||'')}" placeholder="http://127.0.0.1:8999" maxlength="200"><p>填 AstrBot 默认的文转图服务地址即可（同一台机器通常是 http://127.0.0.1:8999）。留空表示只发「封面 + 文案」。</p></div><div class="inline"><button type="button" id="live-card-save" class="button primary">保存卡片设置</button><button type="button" id="live-card-preview-start" class="button">预览开播卡</button><button type="button" id="live-card-preview-end" class="button">预览下播卡</button><button type="button" id="live-card-test" class="button subtle">渲染服务自检</button></div><p>${esc(status)}</p><div id="live-card-preview" hidden></div>`;
}
function renderLiveRows(d){
 liveSnapshot=d;
 for(const k of ['start','stop','auto'])if($('#live-detect-'+k))$('#live-detect-'+k).disabled=k==='start'&&!d.enabled;
 setHTML('#live-schedule',`${esc(!d.enabled?'直播检测关闭':d.control==='stopped'?'已手动停止':d.control==='manual'?'手动检测中':Object.values(d.detection||{}).includes('following')?'时段外，跟踪已开播主播':d.window?.inside===false?'等待检测时段':'自动检测中')} · ${d.running?'本轮检查中':d.nextCheckAt?`下次检查约 ${esc(time(d.nextCheckAt))}`:'暂无检查计划'}。<button class="button subtle" id="live-refresh" type="button">刷新状态与记录</button>`);
 if(renderChanged('#live-subscriptions',[d.subscriptions,d.states,d.errors,d.enabled,d.control,d.detection,d.manualSending]))$('#live-subscriptions').innerHTML=d.subscriptions.length?`<div class="table-wrap"><table><thead><tr><th>主播 / 房间</th><th>状态 / 最近检查</th><th>通知群 / 类型</th><th>操作</th></tr></thead><tbody>${d.subscriptions.map(sub=>{const s=d.states[sub.uid],problem=d.errors?.[sub.uid]?.message||s?.error;return `<tr><td>${s?resultLink('https://live.bilibili.com/'+s.roomId,sub.label||s.name):esc(sub.label||'UID '+sub.uid)}<small>UID ${esc(sub.uid)}${s?` · 房间 ${esc(s.roomId)}`:''}</small>${s?.title?`<small>${esc(s.title)}</small>`:''}</td><td>${badge(!sub.enabled?'订阅暂停':!d.enabled?'检测关闭':d.control==='stopped'?'手动停止':d.detection?.[sub.uid]==='outside_window'?'等待时段':!s?'等待首次检查':s.stopHits===1?'疑似下播，等待确认':s.status===1?'直播中':s.status===2?'轮播':'未开播',s?.status===1&&d.enabled&&sub.enabled?'':'neutral')}<small>${s?.checkedAt?esc(time(s.checkedAt)):'尚未成功检查'}</small>${d.detection?.[sub.uid]==='following'?'<small>时段外持续跟踪</small>':''}${problem?`<p class="danger">${esc(problem)}</p>`:''}</td><td>${sub.groups.map(esc).join('、')}<small>${[sub.start?'开播':'',sub.end?'下播':''].filter(Boolean).join(' / ')}</small></td><td><button class="button live-edit" data-uid="${esc(sub.uid)}">编辑</button> <button class="button danger live-remove" data-uid="${esc(sub.uid)}">删除</button><div class="inline" style="margin-top:8px"><button class="button live-manual-notify" data-uid="${esc(sub.uid)}" data-kind="start" ${(d.manualSending||[]).includes(sub.uid)?'disabled':''}>手动发开播</button><button class="button live-manual-notify" data-uid="${esc(sub.uid)}" data-kind="end" ${(d.manualSending||[]).includes(sub.uid)?'disabled':''}>手动发下播</button></div></td></tr>`;}).join('')}</tbody></table></div>`:empty('还没有订阅，请在上方添加主播并选择通知群。');
 if(renderChanged('#live-records',[d.records,d.manualSending]))$('#live-records').innerHTML=d.records.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>主播 UID</th><th>群号 / 通知</th><th>发送结果</th></tr></thead><tbody>${d.records.map(r=>`<tr><td>${esc(time(r.time))}</td><td>${esc(r.uid)}</td><td>${esc(r.group)}<small>${r.kind==='start'?'开播':'下播'} · ${r.source==='manual'?'手动':'自动'}</small></td><td>${badge(r.status==='sent'?'已发送':r.status==='queued'?'排队中':r.status==='cancelled'?'未发送，已取消':r.status==='uncertain'?'失败／结果未知':'提交中／结果未知',r.status==='sent'?'':'neutral')}${r.message?`<small>${esc(r.message)}</small>`:''}${['uncertain','cancelled'].includes(r.status)?`<button class="button live-manual-notify" data-uid="${esc(r.uid)}" data-kind="${esc(r.kind)}" data-record="${esc(r.id)}" ${(d.manualSending||[]).includes(r.uid)?'disabled':''}>仅补发此群</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有开播或下播通知记录。');
}
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['live-settings-form','live-subscription-form'].includes(form.id))return;event.preventDefault();if(busy)return;
 busy=true;const button=form.querySelector('[type="submit"]');button.disabled=true;
 try{
  const d=form.id==='live-settings-form'?await post('/live/settings',{revision:liveData.revision,enabled:$('#live-enabled').checked,intervalSeconds:Number($('#live-interval').value),scheduleEnabled:$('#live-window-enabled').checked,windows:readLiveWindows(),continueUntilEnd:$('#live-follow').checked}):await post('/live/subscription',{revision:liveData.revision,input:$('#live-input').value,type:$('#live-input-type').value,label:$('#live-label').value,groups:$('#live-groups').value,enabled:$('#live-sub-enabled').checked,start:$('#live-start').checked,end:$('#live-end').checked});
  liveDirty.delete(form.id);dirty=liveDirty.size>0;liveData=d;renderLiveRows(d);toast(form.id==='live-settings-form'?'通知设置已保存':'主播已验证，订阅已保存');
 }catch(e){error(e.message);}finally{busy=false;button.disabled=false;}
});
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b||(!b.id.startsWith('live-')&&!b.classList.contains('live-edit')&&!b.classList.contains('live-remove')&&!b.classList.contains('live-manual-notify')))return;
 if(busy){liveFeedback('正在处理上一项操作，请稍候。');return;}
 if(b.id==='live-window-add'||b.id.startsWith('live-window-remove-')){
  liveWindows=readLiveWindows();
  if(b.id==='live-window-add'){if(liveWindows.length>=12)return;liveWindows.push({startTime:'',endTime:''});}
  else liveWindows.splice(Number(b.id.slice('live-window-remove-'.length)),1);
  liveDirty.add('live-settings-form');dirty=true;renderLiveWindows();return;
 }
 if(b.id==='live-card-save'){
  busy=true;b.disabled=true;
  try{
   const patch={liveCard:$('#live-card-toggle').checked,liveCardPersona:$('#live-card-persona').value,liveCardTheme:$('#live-card-theme').value,liveCardDecor:$('#live-card-decor').value,liveCardAvatarPosition:$('#live-card-avatar-pos').value,liveCardRenderUrl:$('#live-card-url').value.trim()};
   await post('/config',{config:patch,revision,cookieAction:'keep'});
   const fresh=await api('/config');config=fresh.config;revision=fresh.revision;
   toast('卡片设置已保存');await renderLiveCardPanel();
  }catch(e){error(e.message);}finally{busy=false;b.disabled=false;}return;
 }
 if(b.id==='live-card-preview-start'||b.id==='live-card-preview-end'){
  if(dirty){liveFeedback('有未保存的表单，请先保存或刷新放弃修改，再预览。');return;}
  const kind=b.id.endsWith('end')?'end':'start';const view=$('#live-card-preview');busy=true;b.disabled=true;
  view.hidden=false;view.innerHTML=empty('正在渲染预览，请稍候…');
  try{
   const d=await post('/live/card/preview',{kind});
   view.innerHTML=`<div class="preview-card"><img src="${esc(d.image)}" alt="直播通知卡片预览"><pre class="preview-text">${esc(d.text)}</pre></div><p>预览使用示例数据（主播：朱朱白白喵），不会请求 B站，也不会向 QQ 发送消息。图片约 ${Math.round(d.bytes/1024)} KB${(d.stickerProblems||[]).length?` · 贴纸提示：${esc(d.stickerProblems.join('；'))}`:''}</p>`;
  }catch(e){view.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}finally{busy=false;b.disabled=false;}return;
 }
 if(b.id==='live-card-test'){
  const view=$('#live-card-preview');busy=true;b.disabled=true;view.hidden=false;view.innerHTML=empty('正在检测渲染服务…');
  try{
   const d=await post('/live/card/test',{});
   view.innerHTML=d.ok?`<div class="notice">渲染服务正常，用时约 ${d.ms} ms，输出约 ${Math.round(d.bytes/1024)} KB。</div>`:`<div class="notice error">${esc(d.hint||'渲染服务不可用。')}</div>`;
  }catch(e){view.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}finally{busy=false;b.disabled=false;}return;
 }
 if(b.id==='live-manual-cancel'){manualIntent=null;$('#live-manual-panel').hidden=true;liveFeedback('已取消，未发送通知。');return;}
 if(b.classList.contains('live-manual-notify')||b.id==='live-manual-send'){
  if(dirty){liveFeedback('有未保存的表单，请先保存或刷新放弃修改，再发送通知。');return;}
  if(b.classList.contains('live-manual-notify')){prepareManualNotification(b);return;}
  if(!manualIntent){liveFeedback('请先选择需要发送的开播或下播通知。');return;}
  busy=true;b.disabled=true;const intent=manualIntent;manualIntent=null;liveFeedback('正在提交手动通知，请稍候…',false);
  try{
   const d=await post('/live/notify',intent);nextRefreshAt=0;renderLive(d);liveFeedback('手动通知已排队，请查看「最近通知」中的发送结果。');
  }catch(e){$('#live-manual-panel').hidden=true;liveFeedback('提交未完成：'+e.message+' 请刷新最近通知并检查群消息，再决定是否补发。');error(e.message);}
  finally{busy=false;b.disabled=false;}return;
 }
 if(b.id.startsWith('live-detect-')){
  if(dirty){liveFeedback('请先保存表单或刷新放弃修改，再操作。');return;}
  busy=true;b.disabled=true;try{
   const d=await post('/live/control',{revision:liveData.revision,action:b.id.slice('live-detect-'.length)});
   nextRefreshAt=0;liveData=d;renderLiveRows(d);liveFeedback('检测控制已生效。');
  }catch(e){liveFeedback(e.message);error(e.message);}finally{busy=false;b.disabled=false;}return;
 }
 if(b.classList.contains('live-edit')){if(dirty&&!confirm('载入此订阅会替换未保存表单，确定继续吗？'))return;const sub=liveData.subscriptions.find(s=>s.uid===b.dataset.uid);if(!sub)return;
  $('#live-input-type').value='uid';$('#live-input').value=sub.uid;$('#live-label').value=sub.label;$('#live-groups').value=sub.groups.join('\n');$('#live-sub-enabled').checked=sub.enabled;$('#live-start').checked=sub.start;$('#live-end').checked=sub.end;$('#live-form-title').textContent='编辑订阅 · UID '+sub.uid;$('#live-subscription-form').scrollIntoView({behavior:'smooth',block:'center'});return;
 }
 if(b.id==='live-reset-form'){if(dirty&&!confirm('清空尚未保存的订阅表单？'))return;$('#live-subscription-form').reset();liveDirty.delete('live-subscription-form');dirty=liveDirty.size>0;$('#live-form-title').textContent='添加／修改订阅';return;}
 if(b.id==='live-refresh'){if(dirty){toast('请先保存表单，或使用右上角刷新并放弃修改。');return;}await navigate('live');return;}
 if(b.classList.contains('live-remove')&&!confirm('删除此主播订阅？已提交的群消息无法撤回。'))return;
 if(b.classList.contains('live-remove')&&dirty){toast('请先保存或清空未保存的表单。');return;}
 busy=true;b.disabled=true;
 try{
  if(b.classList.contains('live-remove')){renderLive(await post('/live/remove',{revision:liveData.revision,uid:b.dataset.uid}));toast('订阅已删除');}
  if(b.id==='live-load-groups'){const d=await api('/groups');$('#live-group-options').innerHTML=d.groups.length?`<label for="live-group-select">选择一个群</label><div class="inline"><select id="live-group-select">${d.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}（${esc(g.id)}）</option>`).join('')}</select><button type="button" class="button" id="live-add-group">加入通知群</button></div>`:empty('机器人暂无可用群聊。');}
  if(b.id==='live-add-group'){const values=new Set($('#live-groups').value.split(/[\s,，;；]+/).filter(Boolean));values.add($('#live-group-select').value);$('#live-groups').value=[...values].join('\n');liveDirty.add('live-subscription-form');dirty=true;}
 }catch(e){error(e.message);}finally{busy=false;b.disabled=false;}
});
